import{_ as l,a0 as s,w as d,s as u,I as o,x as n,a1 as i,A as r,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse(`{"title":"Microsoft Linux 没来，但微软用更聪明的办法赢了 | LCTT x X-CMD","titleTemplate":false,"description":"2020 年 TechRepublic Jack Wallen 提议微软发 Microsoft Linux 桌面发行版。没发生——但微软用 WSL+Azure+VS Code+Copilot 这套'嵌入 Linux'路线赢麻了。","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Microsoft Linux 没来，但微软用更聪明的办法赢了 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2020 年 TechRepublic Jack Wallen 提议微软发 Microsoft Linux 桌面发行版。没发生——但微软用 WSL+Azure+VS Code+Copilot 这套'嵌入 Linux'路线赢麻了。"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20201012 Could Microsoft be en route to dumping Windows in favor of Linux.digest","title":"Microsoft Linux 没来，但微软用更聪明的办法赢了","tag":"202010","desc":"2020 年 TechRepublic Jack Wallen 提议微软发 Microsoft Linux 桌面发行版。没发生——但微软用 WSL+Azure+VS Code+Copilot 这套'嵌入 Linux'路线赢麻了。"},"relativePath":"202010/20201012 Could Microsoft be en route to dumping Windows in favor of Linux.digest.md","filePath":"[post].md"}`),f={name:"202010/20201012 Could Microsoft be en route to dumping Windows in favor of Linux.digest.md"},L={class:"table-wrap"};function p(x,t,c,g,m,W){const e=s("Link");return d(),u("div",null,[t[11]||(t[11]=o("h1",{id:"microsoft-linux-没来-但微软用更聪明的办法赢了",tabindex:"-1"},[n("Microsoft Linux 没来，但微软用更聪明的办法赢了 "),o("a",{class:"header-anchor",href:"#microsoft-linux-没来-但微软用更聪明的办法赢了","aria-label":"Permalink to “Microsoft Linux 没来，但微软用更聪明的办法赢了”"},"​")],-1)),o("blockquote",null,[o("p",null,[t[1]||(t[1]=n("老文新评 #062 · ",-1)),i(e,{href:"https://www.zdnet.com/article/linux-based-windows-makes-perfect-sense/",rel:"nofollow noopener"},{default:r(()=>[...t[0]||(t[0]=[n("ZDNet",-1)])]),_:1}),t[2]||(t[2]=n(" · 2020-10-12",-1))])]),t[12]||(t[12]=a('<p>2020 年 10 月，TechRepublic 的 Jack Wallen 写了一篇相当激进的长文——<strong>&quot;微软应该直接发布自己的 Linux 桌面&quot;</strong>，不是 WSL、不是 Linux 子系统，而是 OEM 出厂预装的完整 Linux 发行版，名字都帮你想好了：Microsoft Linux。</p><p>6 年后看这事，<strong>他猜对了一半</strong>——微软确实在 WSL、Azure、VS Code、PowerShell、Edge 这些层面深度拥抱了 Linux。但 OEM 出厂预装 Microsoft Linux？没发生。微软选了另一条路。</p><p>2020 年的微软处于一个微妙的转型期：Azure 已经是云市场老二、Windows 桌面市场开始被 Chromebook 和 Mac 蚕食、WSL 已经迭代到第二代（带真 Linux 内核）、VS Code 成为最流行的跨平台编辑器。那一年也是疫情爆发期，远程办公突然成为主流，Linux 桌面首次真正进入主流企业视野。Wallen 这篇文章正是在这个时间窗口提出「微软应该 all-in Linux」——结合 Eric Raymond 当时那条「桌面战争终战」的论点。</p><h2 id="文章讲了啥" tabindex="-1">文章讲了啥 <a class="header-anchor" href="#文章讲了啥" aria-label="Permalink to “文章讲了啥”">​</a></h2><p>Wallen 的核心论点可以拆成几条：</p><ul><li><strong>Azure 是新摇钱树，Windows 不是</strong>：微软已经在云上赢了，没必要为 Windows 桌面续命</li><li><strong>微软应该&quot;登月式飞跃&quot;</strong>：不是&quot;在 Linux 内核上跑 Windows 界面&quot;，而是直接发布完整的 Microsoft Linux 发行版</li><li><strong>OEM 全切换</strong>：大卖场 PC 出厂直接装 Microsoft Linux，没有&quot;半途而废的余地&quot;</li><li><strong>保留 Windows Defender</strong>：用户需要防钓鱼/恶意 URL，Defender 应该原生集成到 Linux 版</li><li><strong>保留 Microsoft 365</strong>：通过 SaaS 提供，用户感受不到 Windows 没了</li><li><strong>桌面环境二选一或定制</strong>：GNOME/KDE/Pantheon/Xfce 任选，UI 可以做成&quot;看起来像 Windows&quot;</li></ul><p>核心收益：用户得到更稳定更安全的桌面、IT 不用天天修 Windows 漏洞、Linux 社区终于主导桌面。</p><h2 id="这些观点今天还成立吗" tabindex="-1">这些观点今天还成立吗？ <a class="header-anchor" href="#这些观点今天还成立吗" aria-label="Permalink to “这些观点今天还成立吗？”">​</a></h2><div class="table-wrap"><table><thead><tr><th>当时的判断</th><th>现在 (2026)</th><th>评分</th></tr></thead><tbody><tr><td>微软会发完整 Linux 桌面发行版</td><td>没发生，微软选了&quot;嵌入 Linux 到 Windows&quot;路线</td><td>❌</td></tr><tr><td>Azure 才是微软的未来</td><td>Azure 现在是云市场第二，Office 365 + Azure 主导营收</td><td>✅</td></tr><tr><td>OEM 出厂装 Linux 能主导桌面</td><td>Steam Deck 证明了 Linux 桌面可行，但 OEM 没跟</td><td>⚠️</td></tr><tr><td>Windows Defender 应该上 Linux</td><td>Microsoft Defender for Linux 已存在，但定位不同</td><td>⚠️</td></tr><tr><td>用户能接受&quot;看起来像 Windows 的 Linux&quot;</td><td>WSL + Windows 11 实现了类似体验</td><td>⚠️</td></tr></tbody></table></div><h2 id="现在-2026-再读这篇文章" tabindex="-1">现在 (2026) 再读这篇文章 <a class="header-anchor" href="#现在-2026-再读这篇文章" aria-label="Permalink to “现在 (2026) 再读这篇文章”">​</a></h2><p>Wallen 错在他假设微软会做&quot;激进的战略转向&quot;，但微软选了更聪明的渐进路线——把 Linux 嵌入 Windows（WSL）、把 Windows 服务搬到 Linux（SQL Server、Edge、Defender）、把 Linux 体验带给所有人（VS Code、GitHub Codespaces）。</p><p>OEM 没出厂预装 Microsoft Linux，但<strong>Microsoft Surface 现在默认带 WSL，Windows 11 也能跑 Linux GUI 应用</strong>。从用户体验角度，&quot;我既能跑 Windows 软件又能用 Linux 工具&quot;这个目标已经达成，只是实现路径不同。</p><p>更重要的是，Wallen 当年没看到的变量：<strong>AI Agent 时代到来</strong>。2026 年的开发者并不在意「用 Windows 还是 Linux」，他们在乎「AI Agent 能不能跑在本地」。微软押对的是 GitHub Copilot + VS Code + Azure AI 这条路，不是操作系统本身。</p><p>Wallen 2020 年提出「Microsoft Linux」——路径没押对，但 Azure + WSL + VS Code 这套「嵌入 Linux」路线微软走得更好。</p><hr><p><strong>出处</strong></p>',16)),o("div",L,[o("table",null,[t[10]||(t[10]=o("thead",null,[o("tr",null,[o("th",null,"字段"),o("th",null,"值")])],-1)),o("tbody",null,[o("tr",null,[t[4]||(t[4]=o("td",null,"原文（ARR 风险）",-1)),o("td",null,[i(e,{href:"https://www.zdnet.com/article/linux-based-windows-makes-perfect-sense/",rel:"nofollow noopener"},{default:r(()=>[...t[3]||(t[3]=[n("zdnet.com",-1)])]),_:1})])]),o("tr",null,[t[6]||(t[6]=o("td",null,"LCTT 译稿源档",-1)),o("td",null,[i(e,{href:"https://github.com/LCTT/TranslateProject/blob/master/sources/tech/"},{default:r(()=>[...t[5]||(t[5]=[n("github.com/LCTT/TranslateProject",-1)])]),_:1})])]),o("tr",null,[t[8]||(t[8]=o("td",null,"原译",-1)),o("td",null,[i(e,{href:"https://linux.cn/article-12718-1.html"},{default:r(()=>[...t[7]||(t[7]=[n("linux.cn/article-12718-1.html",-1)])]),_:1})])]),t[9]||(t[9]=o("tr",null,[o("td",null,"发布"),o("td",null,"2020-10-12")],-1))])])]),t[13]||(t[13]=o("hr",null,null,-1))])}const h=l(f,[["render",p]]);export{C as __pageData,h as default};
